public static ConfigurationModel loadConfigurationFiles(List<File> files, String workingDirectory) {
    ConfigurationModel defaultConfig;
    try {
        defaultConfig = ConfigurationModel.defaults();
    } catch (UnsupportedOperationException e) {
        throw new RuntimeException("Failed to initialize default configuration", e);
    }

    return files.stream()
        .map(f -> {
            try {
                return TomlUtils.loadConfigurationFile(f, workingDirectory);
            } catch (FlywayException | SecurityException e) {
                throw new RuntimeException("Failed to load configuration file: " + f.getName(), e);
            }
        })
        .reduce(defaultConfig, ConfigurationModel::merge);
}
